{
  "edits": [
    {
      "hint": 1,
      "original": "with only a handful of theaters refusing to screen it",
      "corrected": "with most theaters refusing to screen it"
    },
    {
      "hint": 2,
      "original": "certified by the British Board of Film Classification (BBFC)",
      "corrected": "certified by the Central Board of Film Certification (CBFC)"
    },
    {
      "hint": 3,
      "original": "IMPPA's letter, addressed this time to India's President",
      "corrected": "IMPPA's letter was addressed to Prime Minister Narendra Modi"
    },
    {
      "hint": 4,
      "original": "The association claimed that producers and distributors were receiving government subsidies but still faced intimidation from central authorities",
      "corrected": "The association said producers and distributors are facing intimidation and obstacles"
    },
    {
      "hint": 5,
      "original": "They also alleged that the municipal administration, rather than the state government, had failed to provide a safe environment",
      "corrected": "They alleged that the state government had failed to provide a safe environment"
    },
    {
      "hint": 6,
      "original": ", with some critics even calling it a light-hearted comedy",
      "corrected": ""
    },
    {
      "hint": 7,
      "original": "Film Workers International Council of Europe (FWICE) had celebrated the situation, issuing a statement that it was \"inspiring\" a healthy debate.",
      "corrected": "The Federation of Western India Cine Employees (FWICE) had condemned the ban, calling it 'shocking' that a CBFC-certified film faced such restrictions."
    },
    {
      "hint": 8,
      "original": "portrayal of Gopal Mukherjee, a former British police officer, rather than Gopal Patha, a revolutionary leader",
      "corrected": "portrayal of Gopal Patha (also referred to as Gopal Mukherjee in some references), a key figure purportedly protecting Hindus during the 1946 riots — not a British police officer"
    },
    {
      "hint": 9,
      "original": "His grandson praised the depiction and filed a letter of appreciation to producer Karan Johar, instead of lodging a complaint against director Vivek Ranjan.",
      "corrected": "His grandson expressed disappointment over the portrayal and filed a complaint against director Vivek Agnihotri."
    },
    {
      "hint": 10,
      "original": "The family denied any legal action, and no complaints were recorded.",
      "corrected": "A complaint was filed by the grandson; the family did not deny legal action in that regard."
    }
  ]
}
